 $users=new PosUsers($db);staffError(400,fn()=>$users->save(array_replace($input,['counterIds'=>['missing']]),'admin'));staffError(400,fn()=>$users->save(array_replace($input,['email'=>'OWNER@example.test']),'admin'));$saved=$users->save($input,'admin');$hash=$db->query('SELECT password_hash FROM jingo_pos_users')->fetchColumn();staffCheck(password_verify($input['password'],$hash)&&!password_verify('different-test-password',$hash),'Password storage/verify');staffCheck($saved['version']===1&&!isset($saved['password'])&&!isset($saved['password_hash']),'Save leaked password');staffError(409,fn()=>$users->save($input,'admin'));staffError(409,fn()=>$users->save(array_replace($input,['id'=>staffId(2),'email'=>'STAFF@example.test']),'admin'));staffError(409,fn()=>$users->save(array_replace($noPassword,['id'=>staffId(99),'version'=>1]),'admin'));
