 $updated=$users->save(array_replace($saved,['name'=>'Tên mới','counterIds'=>['Main'],'permissions'=>['COLLECT']]),'admin');staffCheck($updated['version']===2&&$db->query('SELECT password_hash FROM jingo_pos_users')->fetchColumn()===$hash,'Metadata changed hash/version');staffCheck((int)$db->query('SELECT COUNT(*) FROM jingo_pos_sessions')->fetchColumn()===2&&(int)$db->query('SELECT COUNT(*) FROM jingo_sessions')->fetchColumn()===1,'Revocation crossed roles/admin/other staff');
