 $race=function(array $bodies)use($name):array{$workers=[];foreach($bodies as $body){$pipes=[];$proc=proc_open([PHP_BINARY,__DIR__.'/pos-users-worker.php',$name,base64_encode(json_encode($body))],[['pipe','r'],['pipe','w'],['pipe','w']],$pipes);fclose($pipes[0]);$workers[]=[$proc,$pipes];}$out=[];foreach($workers as [$proc,$pipes]){$out[]=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);staffCheck(proc_close($proc)===0,$error);}sort($out);return $out;};staffCheck($race([array_replace($restored,['name'=>'A']),array_replace($restored,['name'=>'B'])])===['conflict','saved'],'Concurrent update overwrote version');staffCheck($race([array_replace($input,['id'=>staffId(20),'email'=>'race@example.test']),array_replace($input,['id'=>staffId(21),'email'=>'RACE@example.test'])])===['conflict','saved'],'Concurrent email creation');
