 echo "PASS: staff schema/UTF16/email, immutable IDs/version, admin email conflict, native password hashes/reset/privacy, archived/case-sensitive scopes, disable/restore, atomic role-specific session revocation/audit rollback, transfer fields and concurrent update/email creation.\n";
}finally{if($db&&$db->inTransaction())$db->rollBack();$db=null;$server->exec("DROP DATABASE `$name`");}
